-- IFRS 15 Staged Journal Approval (Task 6)
-- All journals generated by IFRS 15 calculations are staged here before ERP push.
-- Status lifecycle: draft → pending_review → approved → posted / failed / reversed
-- Rollback: DROP TABLE ifrs15_staged_journals;

CREATE TABLE IF NOT EXISTS ifrs15_staged_journals (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  firm_id         TEXT NOT NULL,

  -- Source of the journal
  source_type     TEXT NOT NULL,
    -- ifrs15_calculation | ifrs15_modification | ifrs15_billing_recon | manual
  source_id       TEXT,       -- portfolio id, modification id, recon id etc.
  contract_id     TEXT,

  -- Journal header
  je_date         DATE NOT NULL,
  description     TEXT,
  currency        TEXT NOT NULL DEFAULT 'AED',
  reference       TEXT,

  -- Double-entry lines stored as JSONB array for flexibility:
  -- [{"account": "...", "account_code": "...", "debit": 0, "credit": 0, "memo": "..."}]
  lines           JSONB NOT NULL DEFAULT '[]',

  -- Totals (computed and stored for quick validation)
  total_debit     NUMERIC(18,4) NOT NULL DEFAULT 0,
  total_credit    NUMERIC(18,4) NOT NULL DEFAULT 0,

  -- COA validation
  coa_validated   BOOLEAN DEFAULT FALSE,
  coa_errors      JSONB,

  -- ERP target
  erp_type        TEXT,   -- zoho_books | tally_prime | sap_b1 | oracle_netsuite | manual
  erp_ref         TEXT,
  erp_response    JSONB,

  -- Status lifecycle
  status          TEXT NOT NULL DEFAULT 'draft',
    -- draft | pending_review | approved | posted | failed | reversed

  -- Workflow actors
  prepared_by     TEXT,
  submitted_at    TIMESTAMPTZ,
  reviewer_id     TEXT,
  reviewed_at     TIMESTAMPTZ,
  approved_by     TEXT,
  approved_at     TIMESTAMPTZ,
  posted_at       TIMESTAMPTZ,
  failure_reason  TEXT,
  reversed_by     TEXT,
  reversed_at     TIMESTAMPTZ,
  reversal_of     UUID REFERENCES ifrs15_staged_journals(id),

  created_at      TIMESTAMPTZ DEFAULT NOW(),
  updated_at      TIMESTAMPTZ DEFAULT NOW()
);

-- SOD: reviewer cannot be the preparer
ALTER TABLE ifrs15_staged_journals
  ADD CONSTRAINT chk_journal_no_self_approval
  CHECK (reviewer_id IS NULL OR reviewer_id <> prepared_by);

-- Journal must balance (debit == credit) — enforced at app layer; db check as backstop
ALTER TABLE ifrs15_staged_journals
  ADD CONSTRAINT chk_journal_balanced
  CHECK (ABS(total_debit - total_credit) < 0.01);

ALTER TABLE ifrs15_staged_journals
  ADD CONSTRAINT chk_journal_status
  CHECK (status IN ('draft','pending_review','approved','posted','failed','reversed'));

CREATE INDEX IF NOT EXISTS idx_ifrs15_journals_firm_status
  ON ifrs15_staged_journals(firm_id, status);

CREATE INDEX IF NOT EXISTS idx_ifrs15_journals_firm_date
  ON ifrs15_staged_journals(firm_id, je_date DESC);

CREATE INDEX IF NOT EXISTS idx_ifrs15_journals_source
  ON ifrs15_staged_journals(source_type, source_id);

-- ── Audit trail ───────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS ifrs15_journal_audit (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  journal_id  UUID REFERENCES ifrs15_staged_journals(id) ON DELETE CASCADE,
  action      TEXT NOT NULL,
  actor       TEXT,
  old_status  TEXT,
  new_status  TEXT,
  note        TEXT,
  created_at  TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ifrs15_journal_audit_journal_id
  ON ifrs15_journal_audit(journal_id);

-- ── Auto-update trigger ───────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION update_ifrs15_journal_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS ifrs15_journal_updated_at ON ifrs15_staged_journals;
CREATE TRIGGER ifrs15_journal_updated_at
  BEFORE UPDATE ON ifrs15_staged_journals
  FOR EACH ROW EXECUTE FUNCTION update_ifrs15_journal_updated_at();

-- ── Grants ────────────────────────────────────────────────────────────────────

GRANT ALL ON TABLE ifrs15_staged_journals TO anon, authenticated, service_role;
GRANT ALL ON TABLE ifrs15_journal_audit   TO anon, authenticated, service_role;

NOTIFY pgrst, 'reload schema';
